<script>import {snapshot,clock} from '../state.js';import {nodeState,sessionGet,sessionSet} from '../lib.js';import NodeTable from '../components/NodeTable.svelte';import Icon from '../components/Icon.svelte';let search=sessionGet('nodes.search',''),filter=sessionGet('nodes.filter','all'),sort=sessionGet('nodes.sort','name');$: sessionSet('nodes.search',search);$: sessionSet('nodes.filter',filter);$: sessionSet('nodes.sort',sort);$: nodes=($snapshot?.nodes||[]).filter(n=>(filter==='all'||nodeState(n,$snapshot,$clock)===filter)&&(n.name+' '+n.address+' '+n.dc+' '+n.rack).toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==='state'?String(a.state).localeCompare(String(b.state)):sort==='load'?(b.load_bytes||0)-(a.load_bytes||0):String(a.name).localeCompare(String(b.name)));
</script>
<section class="panel"><div class="toolbar"><label class="search"><Icon name="search" size={16}/><input id="node-search" bind:value={search} aria-label="ノード検索" placeholder="名前・IP・DCで検索"/></label><label class="inline-field">状態 <select bind:value={filter} aria-label="ノード状態で絞り込み"><option value="all">すべて</option><option value="healthy">正常</option><option value="warning">注意</option><option value="critical">異常</option><option value="unknown">未確認</option></select></label><label class="inline-field">並び順 <select bind:value={sort}><option value="name">名前</option><option value="state">状態</option><option value="load">データ量</option></select></label><span class="quiet count">{nodes.length} / {$snapshot?.nodes.length||0} 台</span></div><NodeTable {nodes} detailed/></section>
<p class="hint">チェックは表示中の観測元からの結果です。ノード名を選択すると、systemd・ローカルREST・メトリクス・方向別の接続を確認できます。</p>
